mapper.select:
SELECT a.menu_id AS menuId ,a.parent_id AS parentId ,a.menu_name AS menuName ,a.menu_path AS menuPath ,a.icon AS icon ,a.sort_order AS sortOrder ,a.menu_level AS menuLevel ,a.menu_type AS menuType ,a.use_yn AS useYn FROM tb_menu_mst a WHERE 1 = 1
AND a.menu_name LIKE '%' + #{menuName} + '%'
AND a.menu_type = #{menuType}
AND a.use_yn = #{useYn}
ORDER BY a.menu_level ,a.parent_id ,a.sort_order

mapper.update:
UPDATE tb_menu_mst
SET    parent_id  = #{parentId}
      ,menu_name  = #{menuName}
      ,menu_path  = #{menuPath}
      ,icon       = #{icon}
      ,sort_order = #{sortOrder}
      ,menu_level = #{menuLevel}
      ,menu_type  = #{menuType}
      ,use_yn     = #{useYn}
      ,upd_id     = 'SYSTEM'
      ,upd_dt     = GETDATE()
WHERE menu_id = #{menuId}

UPDATE tb_menu_mst
SET    use_yn   = #{useYn}
      ,upd_id   = 'SYSTEM'
      ,upd_dt   = GETDATE()
WHERE menu_id   = #{menuId}

mapper.select:
SELECT c.menu_id AS grpMenuId ,c.menu_name AS grpMenuName ,b.menu_id AS menuId ,b.menu_name AS menuName ,ISNULL(a.read_yn, 'N') AS readYn ,ISNULL(a.write_yn, 'N') AS writeYn FROM tb_menu_mst b JOIN tb_menu_mst c ON b.parent_id = c.menu_id JOIN tb_menu_mst p ON c.parent_id = p.menu_id LEFT JOIN tb_menu_auth a ON a.menu_id = b.menu_id AND a.user_id = #{userId} WHERE b.menu_level = 3 AND b.use_yn = 'Y' AND c.menu_level = 2 AND c.use_yn = 'Y' AND p.menu_level = 1 AND p.use_yn = 'Y'
AND c.menu_id = #{grpMenuId}
ORDER BY p.sort_order ,c.sort_order ,b.sort_order ,b.menu_id

update.foreach:
UPDATE tb_menu_auth
SET      read_yn = #{item.readYn}
        ,write_yn = #{item.writeYn}
        ,upd_id = 'SYSTEM'
        ,upd_dt = GETDATE()
WHERE  user_id = #{userId}
AND    menu_id = #{item.menuId}
